triggers.prompt:
阅读下列程序，写出输出结果。
#include <stdio.h>
int f(int n)
{
    if (n == 1) return 1;
    else return n + f(n - 1);
}
int main(void)
{
    printf("%d", f(5));
    return 0;
}
要求：用两列栈表（调用层 | 回代求值）写出跟踪过程，再给最终输出。

阅读下列程序，写出输出结果。
#include <stdio.h>
int fun(int a[], int n)
{
    if (n >= 1)
        return fun(a, n - 1) + a[n - 1];
    else
        return 0;
}
int main(void)
{
    int x[7] = {1, 2, 3, 4, 5, 6, 7}, s;
    s = fun(x, 7);
    printf("%d", s);
    return 0;
}

阅读下列程序，写出输出结果，并说明每行输出时 b 和 c 的值从何而来。
#include <stdio.h>
int f(int a)
{
    int b = 3;
    static int c = 3;
    b++;
    c++;
    return a + b + c;
}
int main(void)
{
    int a = 3, i;
    for (i = 0; i < 3; i++)
        printf("%4d", f(a));
    return 0;
}

