写出下列程序的输出结果，并用'值传递'说明原因。
#include <stdio.h>
void s(int n)
{
    int i;
    for (i = n - 1; i >= 1; i--) n = n + i;
    printf("in_s=%d\n", n);
}
int main(void)
{
    int n = 100;
    s(n);
    printf("out_n=%d\n", n);
    return 0;
}

下列程序想通过函数把数组每个元素都加 1，能否成功？输出什么？为什么 addone 的形参写成 int a[] 时长度可以不写？
#include <stdio.h>
void addone(int a[], int n)
{
    int i;
    for (i = 0; i < n; i++) a[i] += 1;
}
int main(void)
{
    int sco[3] = {10, 20, 30}, i;
    addone(sco, 3);
    for (i = 0; i < 3; i++) printf("%d ", sco[i]);
    return 0;
}

edges.prompt:
下列程序能否编译通过？输出什么？把 `extern int w;` 改成 `int w;` 又会发生什么？
#include <stdio.h>
int l = 3, w = 4, h = 5;
int vs(int l, int w)
{
    extern int h;
    int v;
    v = l * w * h;
    return v;
}
int main(void)
{
    extern int w;
    int l = 5;
    printf("l=%d,w=%d,h=%d,v=%d", l, w, h, vs(l, w));
    return 0;
}
